// Hero figure. A straight port of Aller Studio's hero renderer (their settings, shaders, dust
// zones, head tracking, blur-in and hover glitch), running on our own faceless mannequin bust
// (assets/hero/bust.glb, generated by scratchpad mesh/bust.mjs). The bust is built in their
// coordinate space (neck pivot y 0.66, chin 0.73, head top 0.97), so all their numbers apply as-is.
// The older statue (statue.glb) still works: set MESH to "statue".
import * as THREE from './vendor/three.module.min.js';
import { GLTFLoader } from './vendor/GLTFLoader.js';
import { mergeVertices } from './vendor/BufferGeometryUtils.js';

const a = {
  frameHalfH: .325, target: [.06, .667], boxAspect: 658 / 911, baseYaw: -.7, headMaxYaw: .85, lookYaw: 1, lookPitch: .5,
  bodyFollow: .22, headSpeed: 3.2, idleAfter: 2.8, particles: 79200, cornerAim: [1, 1], dustAngle: 0, dustFan: 28,
  dustBirthEdge: .3, dustZones: [.68, .2, .12], shoulderShare: .1, shoulderFlakes: .06, leftDust: 7e3, leftAngle: 165,
  leftFan: 50, leftReach: .55, leftY: [.38, .62], leftFlakes: .04, faceShare: .22, faceY: [.72, .93], flakes: 1328,
  pecFlakes: 700, pecBox: [.04, .26, .4, .62], lime: [.82, .82, .24], limeShare: .02, mouseRepel: 1, particleSize: 1.1,
  dustReach: .45, dustFade: .65, keyDir: [.75, .35, -.55], key: 1, fillDir: [-.85, .25, .45], fill: .45,
  frontDir: [-.7, .62, .35], front: .85, frontGrain: 1.15, topDir: [.1, 1, .15], top: .8, lightAlpha: .55, rimAlpha: .85,
  neckLo: .56, neckHi: .76, spec: .05, grainPx: 3.4, ridge: 1.25, chestGrain: .45, tone: .04, shade: 1.5,
  flakeShare: .00455, flakeSpeed: .585, flakeTravel: 1.8, flakeGap: .016,
};
const MESH = "bust";
const FITS = {
  // bust: their neck numbers, with the twist kept to the neck itself (our traps rise higher than theirs)
  bust: { file: "assets/hero/bust.glb", native: true, smooth: 3, ridgeFrom: 0.2, neckLo: 0.62, neckHi: 0.76, neckX: [0.05, 0.09], headOpen: [0.66, 0.71] },
  statue: {
  file: "assets/hero/statue.glb",
  scale: 0.74, lift: 0.2012,     // y' = 0.74 y + 0.2012: our chin (0.62) lands on their pivot (0.66)
  smooth: 12,                    // Taubin passes over the generated surface
  ridgeFrom: 0.9,                // share of the surface kept below their ridge threshold
  neckX: [0.07, 0.16],           // theirs: 0.05, 0.11 (our neck and jaw are wider)
  headOpen: [0.64, 0.69],        // theirs: 0.69, 0.74 (our jaw starts lower)
  },
};
const FIT = FITS[MESH];

const figure = document.getElementById('hero-figure');
const canvas = document.getElementById('statue');
const reduced = matchMedia('(prefers-reduced-motion: reduce)').matches;
const light = matchMedia('(max-width: 1023px), (pointer: coarse)').matches;
const force3d = new URLSearchParams(location.search).has('force3d');

function realGPU() {
  try {
    const c = document.createElement('canvas');
    const gl = c.getContext('webgl2', { failIfMajorPerformanceCaveat: !force3d });
    if (!gl) return false;
    const ext = gl.getExtension('WEBGL_debug_renderer_info');
    const name = ext ? String(gl.getParameter(ext.UNMASKED_RENDERER_WEBGL)) : '';
    gl.getExtension('WEBGL_lose_context')?.loseContext();
    return force3d || !/swiftshader|llvmpipe|softpipe|software|basic render/i.test(name);
  } catch { return false; }
}
const still = () => figure.classList.add('is-still');
if (!realGPU()) still();
else loadMesh().then((mesh) => {
  const s = createSilhouette(THREE, canvas, mesh, { reduced, light, appear: true, glitch: true });
  canvas.classList.add('is-ready');
  s.appear();
  let visible = true;
  const sync = () => s.setRunning(visible && !document.hidden);
  new IntersectionObserver(([en]) => { visible = en.isIntersecting; sync(); }).observe(canvas);
  document.addEventListener('visibilitychange', sync);
  sync();
}).catch((e) => { console.warn('statue:', e); still(); });

// ---- our mesh, in their format: pos, nrm (-1..1), crv (0..1 convexity), idx
async function loadMesh() {
  const gltf = await new GLTFLoader().loadAsync(FIT.file);
  let src = null;
  gltf.scene.traverse((o) => { if (o.isMesh && !src) src = o; });
  if (!src) throw new Error('no mesh');
  let geo = new THREE.BufferGeometry();
  geo.setAttribute('position', src.geometry.attributes.position.clone());
  if (src.geometry.index) geo.setIndex(src.geometry.index.clone());
  geo = mergeVertices(geo, 1e-5);
  if (!FIT.native) {
    geo.applyMatrix4(new THREE.Matrix4().makeRotationY(Math.PI));
    geo.computeBoundingBox();
    const bb = geo.boundingBox, h = bb.max.y - bb.min.y;
    geo.translate(-(bb.min.x + bb.max.x) / 2, -bb.min.y, -(bb.min.z + bb.max.z) / 2);
    geo.scale(FIT.scale / h, FIT.scale / h, FIT.scale / h);
    geo.translate(0, FIT.lift, 0);
  }

  const pos = geo.attributes.position.array, idx = geo.index.array, F = pos.length / 3;
  // neighbours
  const nb = Array.from({ length: F }, () => new Set());
  for (let t = 0; t < idx.length; t += 3) {
    const i = idx[t], j = idx[t + 1], k = idx[t + 2];
    nb[i].add(j).add(k); nb[j].add(i).add(k); nb[k].add(i).add(j);
  }
  const N = nb.map((s) => Int32Array.from(s));
  // Taubin smoothing: irons out the generated surface's small lumps, keeps the carved forms
  {
    const tmp = new Float32Array(pos.length);
    const step = (f) => {
      for (let i = 0; i < F; i++) {
        let x = 0, y = 0, z = 0; const n = N[i].length; if (!n) { tmp.set(pos.subarray(i * 3, i * 3 + 3), i * 3); continue; }
        for (const j of N[i]) { x += pos[j * 3]; y += pos[j * 3 + 1]; z += pos[j * 3 + 2]; }
        tmp[i * 3] = pos[i * 3] + f * (x / n - pos[i * 3]);
        tmp[i * 3 + 1] = pos[i * 3 + 1] + f * (y / n - pos[i * 3 + 1]);
        tmp[i * 3 + 2] = pos[i * 3 + 2] + f * (z / n - pos[i * 3 + 2]);
      }
      pos.set(tmp);
    };
    for (let it = 0; it < FIT.smooth; it++) { step(0.5); step(-0.53); }
    geo.attributes.position.needsUpdate = true;
  }
  geo.computeVertexNormals();
  let nrm = Float32Array.from(geo.attributes.normal.array);
  // one pass of normal smoothing: the generated surface is a little lumpy
  {
    const out = new Float32Array(nrm.length);
    for (let i = 0; i < F; i++) {
      let x = nrm[i * 3] * 2, y = nrm[i * 3 + 1] * 2, z = nrm[i * 3 + 2] * 2;
      for (const j of N[i]) { x += nrm[j * 3]; y += nrm[j * 3 + 1]; z += nrm[j * 3 + 2]; }
      const l = Math.hypot(x, y, z) || 1;
      out[i * 3] = x / l; out[i * 3 + 1] = y / l; out[i * 3 + 2] = z / l;
    }
    nrm = out;
  }
  // convexity: how far the neighbours fall behind the tangent plane
  let k = new Float32Array(F);
  for (let i = 0; i < F; i++) {
    let s = 0, c = 0;
    for (const j of N[i]) {
      const dx = pos[i * 3] - pos[j * 3], dy = pos[i * 3 + 1] - pos[j * 3 + 1], dz = pos[i * 3 + 2] - pos[j * 3 + 2];
      const d2 = dx * dx + dy * dy + dz * dz; if (d2 < 1e-12) continue;
      s += (nrm[i * 3] * dx + nrm[i * 3 + 1] * dy + nrm[i * 3 + 2] * dz) / Math.sqrt(d2); c++;
    }
    k[i] = c ? s / c : 0;
  }
  for (let it = 0; it < 2; it++) {
    const o = new Float32Array(F);
    for (let i = 0; i < F; i++) { let s = k[i] * 2, c = 2; for (const j of N[i]) { s += k[j]; c++; } o[i] = s / c; }
    k = o;
  }
  // map so only the sharpest carved edges clear their ridge threshold (0.24) and the very top saturate (0.60)
  const sorted = Float32Array.from(k).sort();
  const lo = sorted[Math.floor(F * FIT.ridgeFrom)], hi = sorted[Math.floor(F * 0.995)];
  const crv = new Float32Array(F);
  for (let i = 0; i < F; i++) crv[i] = Math.min(1, Math.max(0, 0.24 + (k[i] - lo) / (hi - lo || 1) * 0.36));
  return { pos: Float32Array.from(pos), nrm, crv, idx: Uint32Array.from(idx) };
}

